def restore_ips(s):
    out = []
    def go(i, parts):
        if len(parts) == 4:
            if i == len(s):
                out.append('.'.join(parts))
            return
        for l in (1, 2, 3):
            piece = s[i:i + l]
            if len(piece) == l and (l == 1 or piece[0] != '0') and int(piece) <= 255:
                go(i + l, parts + [piece])
    go(0, [])
    return sorted(out)
